import React from 'react';
import {ScrollView, Text, TouchableOpacity} from 'react-native';
import {Theme} from '../../types/interfaces';
import {TocEntry} from '../../lib/rules/types';
import styles from '../../styles/RulesScreenStyles';

interface RulesTocProps {
  entries: TocEntry[];
  onAnchorPress: (anchor: string) => void;
  theme: Theme;
}

const RulesToc = ({entries, onAnchorPress, theme}: RulesTocProps) => (
  <ScrollView
    testID="rules-toc-panel"
    style={{
      ...styles.tocPanel,
      borderTopColor: theme.dividerColor,
      borderBottomColor: theme.dividerColor,
      backgroundColor: theme.translucentBackgroundColor,
    }}>
    {entries.map((entry, index) => (
      <TouchableOpacity
        key={`${entry.anchor}-${index}`}
        testID={`rules-toc-item-${index}`}
        onPress={() => onAnchorPress(entry.anchor)}
        style={{
          ...styles.tocItem,
          paddingLeft: 12 + Math.max(0, entry.level - 1) * 10,
        }}>
        <Text style={{...styles.tocText, color: theme.foregroundColor}}>
          {entry.title}
        </Text>
      </TouchableOpacity>
    ))}
  </ScrollView>
);

export default RulesToc;
